     7	public class DatabaseConfig {
     8	    private static String dbUrl;
     9	    private static String dbUser;
    10	    private static String dbPassword;
    11	
    12	    static {
    13	        dbUrl = System.getenv("DB_URL");
    14	        dbUser = System.getenv("DB_USER");
    15	        dbPassword = System.getenv("DB_PASSWORD");
    16	
    17	        if (dbUrl == null || dbUser == null || dbPassword == null) {
    18	            throw new RuntimeException("Database configuration missing: DB_URL, DB_USER, DB_PASSWORD");
    19	        }
    20	    }
    21	
    22	    public static void initialize() {
    23	        try (Connection conn = getConnection()) {
    24	            createSchema(conn);
    25	        } catch (SQLException e) {
    26	            throw new RuntimeException("Failed to initialize database", e);
    27	        }
    28	    }
    29	
    30	    public static Connection getConnection() throws SQLException {
    31	        return DriverManager.getConnection(dbUrl, dbUser, dbPassword);
    32	    }
    33	
    34	    private static void createSchema(Connection conn) throws SQLException {
    35	        String[] statements = {
    36	            """
    37	            CREATE TABLE IF NOT EXISTS rooms (
    38	                number INTEGER PRIMARY KEY,
    39	                type VARCHAR(20) NOT NULL,
    40	                capacity INTEGER NOT NULL,
    41	                nightly_rate NUMERIC(10, 2) NOT NULL
    42	            )
    43	            """,
    44	            """
    45	            CREATE TABLE IF NOT EXISTS reservations (
    46	                id BIGSERIAL PRIMARY KEY,
    47	                room_number INTEGER NOT NULL REFERENCES rooms(number),
    48	                guest_name VARCHAR(255) NOT NULL,
    49	                guest_email VARCHAR(255) NOT NULL,
    50	                guest_cpf VARCHAR(20) NOT NULL,
    51	                check_in DATE NOT NULL,
    52	                check_out DATE NOT NULL,
    53	                guests INTEGER NOT NULL,
    54	                rate_plan VARCHAR(20) NOT NULL,
    55	                nights INTEGER NOT NULL,
    56	                subtotal NUMERIC(10, 2) NOT NULL,
    57	                discount NUMERIC(10, 2),
    58	                total NUMERIC(10, 2) NOT NULL,
    59	                status VARCHAR(20) NOT NULL,
    60	                amount_paid NUMERIC(10, 2) NOT NULL DEFAULT 0,
    61	                refund NUMERIC(10, 2)
    62	            )
    63	            """,
    64	            """
    65	            CREATE TABLE IF NOT EXISTS messages (
    66	                id BIGSERIAL PRIMARY KEY,
    67	                channel VARCHAR(20) NOT NULL,
    68	                to_address VARCHAR(255) NOT NULL,
    69	                subject VARCHAR(255) NOT NULL,
    70	                body TEXT NOT NULL
    71	            )
    72	            """,
    73	            """
    74	            INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES
    75	            (101, 'STANDARD', 2, 249.90),
    76	            (102, 'STANDARD', 2, 249.90),
    77	            (201, 'DELUXE', 3, 389.90),
    78	            (202, 'DELUXE', 3, 389.90),
    79	            (301, 'SUITE', 4, 579.90)
    80	            ON CONFLICT (number) DO NOTHING
    81	            """
    82	        };
    83	
    84	        for (String sql : statements) {
    85	            if (!sql.trim().isEmpty()) {
    86	                try (var stmt = conn.createStatement()) {
    87	                    stmt.execute(sql);
    88	                }
    89	            }
    90	        }
    91	    }
    92	}
