    39	
    40	        app.get("/reports/revenue", ctx -> {
    41	            try {
    42	                String monthStr = ctx.queryParam("month");
    43	                if (monthStr == null || monthStr.isEmpty()) {
    44	                    ctx.status(400);
    45	                    ctx.json(error("INVALID_REQUEST", "Month parameter is required"));
    46	                    return;
    47	                }
    48	
    49	                YearMonth month = YearMonth.parse(monthStr);
    50	                String csv = generateRevenueReport(month);
    51	
    52	                ctx.contentType("text/csv; charset=utf-8");
    53	                ctx.result(csv);
    54	            } catch (DateTimeParseException e) {
    55	                ctx.status(400);
    56	                ctx.json(error("INVALID_REQUEST", "Invalid month format"));
    57	            } catch (SQLException e) {
