    63	
    64	    private static String generateOccupancyReport(LocalDate date) throws SQLException {
    65	        var roomRepository = new RoomRepository();
    66	        var reservationRepository = new ReservationRepository();
    67	        var rooms = roomRepository.findAll();
    68	
    69	        StringBuilder csv = new StringBuilder();
    70	        csv.append("room,type,reservation,check_in,check_out\n");
    71	
    72	        int occupiedCount = 0;
    73	        for (var room : rooms) {
    74	            var reservations = reservationRepository.findByRoomAndDate(room.getNumber(), date);
    75	            if (!reservations.isEmpty()) {
    76	                for (var res : reservations) {
    77	                    csv.append(room.getNumber()).append(",")
    78	                        .append(room.getType().name()).append(",")
    79	                        .append(res.getId()).append(",")
    80	                        .append(res.getCheckIn()).append(",")
    81	                        .append(res.getCheckOut()).append("\n");
    82	                    occupiedCount++;
    83	                }
    84	            }
    85	        }
    86	
    87	        csv.append("total,").append(occupiedCount).append("/").append(rooms.size()).append("\n");
    88	
    89	        return csv.toString();
    90	    }
    91	
    92	    private static String generateRevenueReport(YearMonth month) throws SQLException {
    93	        ReservationRepository reservationRepository = new ReservationRepository();
    94	        var reservations = reservationRepository.findByMonth(month.getYear(), month.getMonthValue());
    95	
    96	        StringBuilder csv = new StringBuilder();
    97	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    98	
    99	        java.math.BigDecimal totalAmount = java.math.BigDecimal.ZERO;
   100	        for (var res : reservations) {
   101	            java.math.BigDecimal refund = res.getRefund() != null ? res.getRefund() : java.math.BigDecimal.ZERO;
   102	            java.math.BigDecimal amount = res.getAmountPaid().subtract(refund);
   103	
   104	            if (amount.signum() != 0) {
   105	                csv.append(res.getId()).append(",")
   106	                    .append(res.getRoomNumber()).append(",")
   107	                    .append(res.getCheckIn()).append(",")
   108	                    .append(res.getCheckOut()).append(",")
   109	                    .append(res.getStatus().name()).append(",")
   110	                    .append(formatMoney(amount)).append("\n");
   111	
   112	                totalAmount = totalAmount.add(amount);
   113	            }
   114	        }
   115	
   116	        csv.append("total,").append(formatMoney(totalAmount)).append("\n");
   117	
   118	        return csv.toString();
   119	    }
   120	
   121	    private static String formatMoney(java.math.BigDecimal value) {
   122	        return String.format("%.2f", value);
   123	    }
   124	
   125	    private static Object error(String code, String message) {
   126	        String errorCode = code;
   127	        String errorMessage = message;
   128	        return new Object() {
   129	            public final String error = errorCode;
   130	            public final String message = errorMessage;
   131	        };
   132	    }
   133	}
