     1	package com.pousada.marealta.service;
     2	
     3	import com.pousada.marealta.domain.Reservation;
     4	import com.pousada.marealta.domain.Room;
     5	import com.pousada.marealta.util.MathUtil;
     6	
     7	import java.math.BigDecimal;
     8	import java.time.LocalDate;
     9	import java.time.YearMonth;
    10	
    11	public class PricingService {
    12	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = BigDecimal.valueOf(1.2);
    13	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT_RATE = BigDecimal.valueOf(0.15);
    14	
    15	    public static PricingResult calculatePrice(Room room, LocalDate checkIn, LocalDate checkOut,
    16	                                               Reservation.RatePlan ratePlan) {
    17	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    18	
    19	        BigDecimal nightly = room.getNightlyRate();
    20	        if (isHighSeason(checkIn, checkOut)) {
    21	            nightly = MathUtil.roundHalfEven(nightly.multiply(HIGH_SEASON_MULTIPLIER));
    22	        }
    23	
    24	        BigDecimal subtotal = MathUtil.roundHalfEven(nightly.multiply(BigDecimal.valueOf(nights)));
    25	
    26	        BigDecimal discount = BigDecimal.ZERO;
    27	        if (ratePlan == Reservation.RatePlan.NON_REFUNDABLE) {
    28	            discount = MathUtil.roundHalfEven(subtotal.multiply(NON_REFUNDABLE_DISCOUNT_RATE));
    29	        }
    30	
    31	        BigDecimal total = MathUtil.roundHalfEven(subtotal.subtract(discount));
    32	
    33	        return new PricingResult(nights, subtotal, discount, total);
    34	    }
    35	
    36	    private static boolean isHighSeason(LocalDate checkIn, LocalDate checkOut) {
    37	        LocalDate current = checkIn;
    38	
    39	        while (current.isBefore(checkOut)) {
    40	            int month = current.getMonthValue();
    41	            int dayOfMonth = current.getDayOfMonth();
    42	
    43	            if ((month == 7) ||
    44	                (month == 12 && dayOfMonth >= 15) ||
    45	                (month == 1) ||
    46	                (month == 2)) {
    47	                return true;
    48	            }
    49	
    50	            current = current.plusDays(1);
    51	        }
    52	
    53	        return false;
    54	    }
    55	
    56	    public static class PricingResult {
    57	        public final int nights;
    58	        public final BigDecimal subtotal;
    59	        public final BigDecimal discount;
    60	        public final BigDecimal total;
    61	
    62	        public PricingResult(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
    63	            this.nights = nights;
    64	            this.subtotal = subtotal;
    65	            this.discount = discount;
    66	            this.total = total;
    67	        }
    68	    }
